'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = (value='') => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = value => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(value);
const paths = {
 home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>', grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>', file:'<path d="M14 3H5v18h14V8z"/><path d="M14 3v5h5M8 12h8M8 16h6"/>', book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Z"/><path d="M12 5v15"/>',
 users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9"/><circle cx="9" cy="7" r="4"/><path d="M16 3.1a4 4 0 0 1 0 7.8"/>', layers:'<path d="m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5"/>',
 settings:'<path d="m9 3-1 3-3 1-2 3 2 2-1 3 2 3 3-1 2 3h3l1-3 3-1 2-3-2-2 1-3-2-3-3 1-2-3z"/><circle cx="11.5" cy="11.5" r="3"/>', help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 .5c0 1.5-2.5 2-2.5 3.5m0 3h.01"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>', down:'<path d="m6 9 6 6 6-6"/>', check:'<path d="m5 12 4 4L19 6"/>', plus:'<path d="M12 5v14M5 12h14"/>', arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>', back:'<path d="M20 12H4m6-6-6 6 6 6"/>', close:'<path d="m6 6 12 12M6 18 18 6"/>',
 bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>', edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-4-4L5 15zM14 20h7"/>', expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>', mail:'<rect x="3" y="5" width="18" height="14" rx="1"/><path d="m3 6 9 7 9-7"/>',
 truck:'<path d="M3 5h12v12H3zm12 5h4l3 4v3h-7"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>', pickup:'<path d="m3 8 9-5 9 5v12H3zM3 8h18M8 20v-8h8v8"/>', download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>', image:'<rect x="3" y="3" width="18" height="18" rx="1"/><circle cx="8" cy="8" r="2"/><path d="m21 15-6-6L3 21"/>',
 share:'<circle cx="18" cy="5" r="3"/><circle cx="5" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8 10 7-4M8 14l7 4"/>', megaphone:'<path d="m3 9 17-6v18L3 15zM3 9v6M7 16l2 5h4l-2-4"/>', qr:'<path d="M3 3h6v6H3zm12 0h6v6h-6zM3 15h6v6H3zM15 15h3v3h3v3h-6v-6zm-3-3h3m-3-9v6M3 12h6m12 0h-3m-6 6v3"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>', alert:'<path d="m12 3 10 18H2zM12 9v5m0 3h.01"/>', pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>', search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>', target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 16v5h18v-5"/>', card:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 9h20M6 15h4"/>', building:'<path d="M5 21V3h14v18M2 21h20M9 7h1m4 0h1M9 11h1m4 0h1M9 15h1m4 0h1M10 21v-3h4v3"/>', tag:'<path d="M3 3h8l10 10-8 8L3 11Z"/><circle cx="7.5" cy="7.5" r="1"/>', wallet:'<path d="M20 7H4V4h14v3M4 7v13h17V7zM16 11h5v5h-5z"/>', lock:'<rect x="5" y="10" width="14" height="11" rx="1"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>', globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-5 5-5 13 0 18 5-5 5-13 0-18Z"/>'
};
const icon = name => `<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.file}</svg>`;
const btn = (label,action,type='',extra='')=>`<button type="button" class="btn ${type}" data-action="${action}" ${extra}>${label}</button>`;
const check = (label,bind,value,secondary='')=>`<label class="check-row"><input type="checkbox" data-bind="${bind}" ${value?'checked':''}><span>${label}${secondary?`<small>${secondary}</small>`:''}</span></label>`;
const input = (label,bind,value,extra='',help='')=>`<label class="field"><span>${label}</span><input data-bind="${bind}" value="${esc(value)}" ${extra}>${help?`<small>${help}</small>`:''}</label>`;
const select = (label,bind,value,options,help='')=>`<label class="field"><span>${label}</span><select data-bind="${bind}">${options.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</label>`;
const catalog = {flyers:{name:'Flyers',singular:'flyer',desc:'A polished one-page property overview',meta:'From $0.34 / piece',icon:'file'},brochures:{name:'Brochures',singular:'brochure',desc:'More room for the full property story',meta:'From $0.50 / piece',icon:'book'},postcards:{name:'Postcards',singular:'postcard',desc:'A personal introduction to the neighborhood',meta:'From $0.32 / piece',icon:'mail'},social:{name:'Social Media',desc:'Listing artwork for your social channels',meta:'View product',icon:'share',digital:true,free:true},image:{name:'Image Download',desc:'Ready-to-use listing imagery',meta:'View product',icon:'image',digital:true,free:true},facebook:{name:'Facebook Ad',desc:'Reach a local audience online',meta:'View product',icon:'megaphone',digital:true}};
const templateDefaults=()=>{try{return JSON.parse(localStorage.getItem('apm08-template-defaults'))||{};}catch{return {};}};
const defaultProduct=(id)=>({template:templateDefaults()[id]||'willow',headline:'A place to call home.',description:'Thoughtfully designed spaces. An inviting backyard. Your next chapter begins in South Austin.',photo:'house',reviewed:false,defaultTemplate:Boolean(templateDefaults()[id]),qr:'',method:id==='brochures'?'mail':'ship',qty:100,paper:'matte',pdf:false,sample:false,sampleAddress:null,mailClass:'standard',format:'pdf',optionsOpen:false,shipAddress:{name:'Jordan Ellis · Cedar Realty',street:'214 Barton Springs Road',street2:'Suite 200',city:'Austin',state:'TX',zip:'78704'},pickup:'cedar',pickupDate:'2026-11-09'});
const initial=()=>({version:3,step:0,active:0,selected:['flyers','brochures'],products:{flyers:defaultProduct('flyers'),brochures:defaultProduct('brochures'),postcards:defaultProduct('postcards')},lists:[{id:'neighbors',name:'Willow Lane neighbors',count:100,date:'Oct 28, 2026',type:'Saved list'},{id:'openhouse',name:'October open-house guests',count:38,date:'Oct 25, 2026',type:'CRM import'},{id:'southaustin',name:'South Austin homeowners',count:225,date:'Oct 20, 2026',type:'Saved list'}],listSelections:{brochures:['neighbors'],flyers:['neighbors'],postcards:['neighbors']},reviewStage:0,credits:{promo:false,store:false,ad:false},payment:'visa',split:30,ack:false,costCenter:'',billingComments:'',cardAdded:false,cardLabel:'',orderMode:'approval',event:'new',submitted:false});
let state;
try { const saved=JSON.parse(localStorage.getItem('apm08-order'));state=saved?.version===3?saved:initial(); }catch {state=initial();}
let ui={view:'',drawer:'',error:'',qrStatus:'',qrValue:'',qrOverride:false,temp:{},listSearch:'',audienceDraft:[],radius:{address:'128 Willow Lane',zip:'78704',qty:50,homes:'single',exclude:true,preview:false},promoOpen:false,promoCode:'',templateChoice:'willow',listEditId:'',sampleDraft:{},source:'',cardDraft:{}};
let lastFocus=null;
const save=()=>{try{localStorage.setItem('apm08-order',JSON.stringify(state));localStorage.setItem('apm08-template-defaults',JSON.stringify(Object.fromEntries(Object.entries(state.products).filter(([,p])=>p.defaultTemplate).map(([id,p])=>[id,p.template]))));}catch{}};
const currentId=()=>state.selected[state.active]||state.selected[0]||'flyers';
const product=()=>state.products[currentId()];
const selectedLists=(id=currentId())=>state.lists.filter(l=>(state.listSelections[id]||[]).includes(l.id));
const audienceCount=(id=currentId())=>selectedLists(id).reduce((a,b)=>a+b.count,0);
const qty=(id)=>{const p=state.products[id];return p.method==='mail'?audienceCount(id)+(p.sample?1:0):p.method==='download'?1:Number(p.qty)||0;};
function pricing(id){const p=state.products[id],q=qty(id),unit=id==='flyers'?.34:id==='brochures'?.50:.32;const print=p.method==='download'?0:Math.max(0,q)*(unit+(p.paper==='premium'?.10:0));const fulfillment=p.method==='mail'?4.50+(p.mailClass==='first'?q*.10:0):p.method==='ship'?6:0;const pdf=p.pdf&&p.method!=='download'?5:0;return {print,fulfillment,pdf,total:Math.round((print+fulfillment+pdf)*100)/100,unit};}
const subtotal=()=>state.selected.reduce((t,id)=>t+pricing(id).total,0);
const tax=()=>Math.round(subtotal()/12*100)/100;
function totals(){const sub=subtotal(),t=tax(),promo=state.credits.promo?Math.min(10,sub+t):0,store=state.credits.store?Math.min(20,sub+t-promo):0,ad=state.credits.ad?Math.min(30,sub+t-promo-store):0;return {sub,t,promo,store,ad,balance:Math.max(0,Math.round((sub+t-promo-store-ad)*100)/100)};}
const addressText=a=>a?`${esc(a.name)}<br>${esc(a.street)}${a.street2?`, ${esc(a.street2)}`:''}<br>${esc(a.city)}, ${esc(a.state)} ${esc(a.zip)}`:'';
const ready=(id)=>{const p=state.products[id];return p.reviewed && !deliveryError(id);};
function deliveryError(id){const p=state.products[id];if(p.paper==='unavailable'&&p.method!=='download')return 'Choose an available paper to calculate your price.';if(p.method==='mail'&&!audienceCount(id))return 'Choose at least one mailing list.';if(p.method==='mail'&&p.sample&&!p.sampleAddress)return 'Add an address for the agent sample copy.';if(['ship','pickup'].includes(p.method)&&(!Number.isInteger(Number(p.qty))||p.qty<25||p.qty>5000))return 'Enter a whole quantity between 25 and 5,000.';if(p.method==='ship'&&!p.shipAddress)return 'Add a shipping address.';if(p.method==='pickup'&&!p.pickupDate)return 'Choose a pickup date.';return '';}
function miniArt(id){if(id==='flyers')return `<div class="mini-paper"><img src="assets/willow-house.jpg" alt=""><div class="mini-label">A place to call home.</div><div class="mini-line"></div><div class="mini-line short"></div></div>`;if(id==='brochures')return `<div class="mini-paper brochure"><div class="mini-col"><span>CEDAR REALTY</span><img src="assets/willow-interior.jpg" alt=""><i></i><i></i></div><div class="mini-col"><img src="assets/willow-house.jpg" alt=""><span>A place to call home.</span><i></i><i></i></div></div>`;if(id==='postcards')return `<div class="postcard"><img src="assets/willow-house.jpg" alt=""><div></div></div>`;return `<div class="digital-icon">${icon(catalog[id].icon)}</div>`;}
function qrArt(){return `<svg viewBox="0 0 29 29" aria-label="Illustrative QR placement" role="img"><rect width="29" height="29" fill="white"/><g fill="#304844">${[0,1,2].map((_,i)=>{const x=i===1?21:1,y=i===2?21:1;return `<path d="M${x} ${y}h7v7h-7z"/><path d="M${x+1} ${y+1}h5v5h-5z" fill="white"/><path d="M${x+2} ${y+2}h3v3h-3z"/>`;}).join('')}${Array.from({length:92},(_,i)=>{const x=(i*7+9)%27+1,y=(i*11+8)%27+1;if((x<9&&y<9)||(x>19&&y<9)||(x<9&&y>19))return '';return `<rect x="${x}" y="${y}" width="${i%4?1:2}" height="${i%3?1:2}"/>`;}).join('')}</g></svg>`;}
function proof(id=currentId()){const p=state.products[id],photo=p.photo==='interior'?'interior':'house',dark=p.template==='modern',headline=esc(p.headline||'A place to call home.');if(id==='brochures')return `<div class="proof brochure-proof" style="${dark?'background:#e9edf0;color:#273f53;':''}"><div class="brochure-side"><div class="brochure-logo">Cedar Realty</div><img src="assets/willow-interior.jpg" alt="Sunlit living area in the fictional Willow Lane property"><h4>Room to make<br>yourself at home.</h4><p>${esc(p.description)}<br><br>Discover the warmth of a beautifully considered home, moments from everything you love.</p><div class="proof-contact"><strong>Jordan Ellis</strong><span>Cedar Realty · (512) 555-0148</span><span>jordan@cedarrealty.example</span></div></div><div class="brochure-front"><img src="assets/willow-${photo}.jpg" alt="Fictional property marketing photo"><div class="proof-body"><div class="proof-eyebrow">${state.event==='open'?'Open house':'New listing'} · Austin, Texas</div><h4>${headline}</h4><p class="proof-address">128 Willow Lane · Austin, TX 78704</p><div class="proof-specs"><span>3 BED</span><span>2 BATH</span><span>2,140 SQ FT</span></div><p class="proof-description">Offered at $725,000<br>Find your next chapter with Cedar Realty.</p>${p.qr?`<div class="proof-qr" style="width:24px;height:24px;margin-top:7px">${qrArt()}</div>`:''}</div></div></div>`;return `<div class="proof" style="${dark?'background:#edf0f3;color:#2c4559;':''}"><div class="proof-top"><strong>Cedar Realty</strong><span>${state.event==='open'?'Open house':'Just listed'}</span></div><img src="assets/willow-${photo}.jpg" alt="Exterior of the fictional 128 Willow Lane listing"><div class="proof-body"><div class="proof-eyebrow">A fresh start in South Austin</div><h4>${headline}</h4><p class="proof-address">128 Willow Lane · Austin, TX 78704</p><div class="proof-specs"><span>3 BEDROOMS</span><span>2 BATHROOMS</span><span>2,140 SQ FT</span></div><p class="proof-description">${esc(p.description)}<br>Offered at $725,000</p></div><div class="proof-footer"><div class="proof-monogram">JE</div><div class="proof-contact"><strong>Jordan Ellis</strong><span>Cedar Realty · (512) 555-0148</span><span>jordan@cedarrealty.example</span></div>${p.qr?`<div class="proof-qr">${qrArt()}</div>`:''}</div></div>`;}
function wizard(){return `<nav class="wizard" aria-label="Order steps">${['Product','Design','Delivery','Review'].map((s,i)=>`<button type="button" class="${state.step===i?'active':state.step>i?'done':''}" data-action="step" data-index="${i}" ${state.step===i?'aria-current="step"':''} ${i>state.step?'disabled':''}><span class="step-num">${state.step>i?icon('check'):i+1}</span><span>${s}${state.step>i?'<span class="step-caption">Complete</span>':''}</span></button>`).join('')}</nav>`;}
function productTabs(){return `<nav class="product-tabs" aria-label="Products in this order">${state.selected.map((id,i)=>`<button data-action="product-tab" data-index="${i}" class="${state.active===i?'active':''} ${state.products[id].reviewed?'done':''}"><span class="tab-num">${state.products[id].reviewed?icon('check'):i+1}</span>${catalog[id].name}<small>${state.step===1?(state.products[id].reviewed?'Proof approved':i===state.active?'Customize':'Not reviewed'):state.products[id].method==='mail'?`${qty(id)} pieces · Mail`:state.products[id].method==='download'?'Digital':`${qty(id)} copies · ${state.products[id].method==='ship'?'Ship':'Pickup'}`}</small></button>`).join('')}</nav>`;}
const panelTitle=(title,subtitle,right='')=>`<div class="panel-title"><div><h2>${title}</h2><p>${subtitle}</p></div>${right}</div>`;
const footer=(left,primary,action,back='back',disabled=false)=>`<div class="panel-footer">${left}<div class="footer-actions">${back?btn(icon('back')+' Back',back,'ghost'):''}${btn(primary+' '+icon('arrow'),action,'primary',disabled?'disabled':'')}</div></div>`;
function catalogStep(){return `${panelTitle('Choose your marketing products','Select the materials you need for this listing.',`<span class="small muted">${state.selected.length} selected</span>`)}<div class="content-columns"><section class="form-column"><div class="product-grid">${Object.entries(catalog).map(([id,c])=>`<button class="product-card ${state.selected.includes(id)?'chosen':''}" data-action="select-product" data-id="${id}" ${!c.digital?`aria-pressed="${state.selected.includes(id)}"`:''}>${!c.digital?`<span class="choice-box">${state.selected.includes(id)?icon('check'):''}</span>`:''}<span class="product-art">${miniArt(id)}</span><strong>${c.name}${c.free?'<span class="free">Free</span>':''}</strong><span class="product-desc">${c.desc}</span><span class="product-meta">${c.meta}${c.digital?' →':''}</span></button>`).join('')}</div><p class="catalog-note">Select multiple print products. You’ll customize and review each one.</p></section><aside class="support-column"><div class="support-heading">Your listing</div><img class="property-photo" src="assets/willow-house.jpg" alt="Contemporary property at 128 Willow Lane"><div class="property-caption">128 Willow Lane</div><div class="small muted">Austin, TX 78704 · Offered at $725,000</div><div class="summary-list">${state.selected.map(id=>`<div class="summary-item">${icon(catalog[id].icon)}<span>${catalog[id].name}<small>${id==='brochures'?'Mail to your audience':'Printed for your listing'}</small></span><span class="qty-chip">Selected</span></div>`).join('')||'<p class="small muted">Your selected products will appear here.</p>'}</div><div class="quiet-note">${icon('info')}<span>One listing, one order.<br>Your property and agent details carry across every product.</span></div></aside></div>${footer(`<span class="footer-note">${state.selected.length} print products for this listing</span>`,'Continue to design','to-design','',!state.selected.length)}`;}
function designStep(){const p=product(),id=currentId(),last=state.active===state.selected.length-1;return `${panelTitle('Customize your '+catalog[id].singular,'Start with a template, then check the details in your proof.',`<span class="small muted">Product ${state.active+1} of ${state.selected.length}</span>`)}${productTabs()}<div class="content-columns"><section class="form-column"><div class="section-title"><h3>Template</h3></div><div class="template-row">${miniArt('flyers')}<div class="template-info"><strong>${p.template==='willow'?'The Willow Collection':'Modern Essentials'}</strong><p>${id==='brochures'?'Bi-fold · 11 × 8.5 in':'Portrait · 8.5 × 11 in'} · ${p.template==='willow'?'Warm white':'Slate & white'}</p></div>${btn('Change','templates')}</div><div class="section-title"><h3>Listing details</h3><span class="tiny muted">Used on this ${catalog[id].singular}</span></div>${input('Headline','product.headline',p.headline,'maxlength="55"')}<div class="static-field">${icon('home')}<span>3 bedrooms &nbsp;·&nbsp; 2 bathrooms &nbsp;·&nbsp; 2,140 sq ft<br><small>Offered at $725,000</small></span></div><div class="editing-tools">${btn(icon('edit')+' Edit text & photo','edit-content')}${btn(icon('qr')+(p.qr?' QR code added':' Add QR code'),'qr')}</div><div class="section-title"><h3>Agent details</h3></div><div class="static-field">${icon('users')}<span><strong>Jordan Ellis</strong> · Cedar Realty<br><small>(512) 555-0148 · jordan@cedarrealty.example</small></span></div>${check('Save this as my default '+catalog[id].singular+' template','product.defaultTemplate',p.defaultTemplate)}${ui.error?`<p class="error">${esc(ui.error)}</p>`:''}</section><aside class="support-column"><div class="section-title"><div class="support-heading" style="margin:0">Design proof</div><span class="status-label ${p.reviewed?'ready':''}">${icon(p.reviewed?'check':'clock')}${p.reviewed?'Approved':'Review needed'}</span></div><div class="proof-wrap">${proof()}</div><div class="proof-actions">${btn(icon('expand')+' View larger proof','proof','ghost')}</div><div class="proof-meta">${id==='brochures'?'Outside spread · 11 × 8.5 in':'Front · 8.5 × 11 in'} &nbsp;·&nbsp; Print preview</div><div class="proof-status ${p.reviewed?'ready':''}">${icon(p.reviewed?'check':'info')}<span>${p.reviewed?'This proof is approved. Editing will require a new review.':'Check the address, contact details, and artwork before continuing.'}</span></div></aside></div>${footer(`<span class="footer-note">${p.reviewed?'Proof approved':'Your approval saves this design.'}</span>`,last?'Approve & choose delivery':'Approve & next product','approve-design')}`;}
function deliveryForm(){const p=product(),id=currentId(),q=qty(id);let form=`<div class="section-title"><h3>How should we deliver this?</h3></div><div class="delivery-methods">${[['mail','mail','Mail'],['ship','truck','Ship'],['pickup','pickup','Pickup'],['download','download','Download']].map(([m,i,l])=>`<button class="method ${p.method===m?'active':''}" data-action="method" data-id="${m}" aria-pressed="${p.method===m}">${icon(i)}${l}</button>`).join('')}</div>`;if(p.method==='mail'){form+=`<p class="context-help">Send individual pieces directly to the people on your mailing lists.</p><div class="section-title"><h3>Recipients</h3></div><div class="audience-box"><div class="audience-line">${icon('users')}<span>${selectedLists().length} selected ${selectedLists().length===1?'list':'lists'}</span><strong>${audienceCount()} recipients</strong></div>${selectedLists().map(l=>`<div class="audience-list-row"><span>${esc(l.name)}</span><span>${l.count}</span></div>`).join('')}${selectedLists().length?'':`<p class="small muted">Choose who should receive this ${catalog[id].singular}.</p>`}<button class="text-btn" data-action="audience">Choose mailing lists ${icon('chevron')}</button></div>${select('Mailing class','product.mailClass',p.mailClass,[['standard','Standard · 5–15 business days'],['first','First Class · 3–5 business days']],'Illustrative delivery windows. Timing begins after production.')}<div class="summary-row"><span class="small muted">Printed quantity</span><strong>${q} pieces</strong></div><p class="tiny muted" style="margin-top:-7px">${audienceCount()} recipients${p.sample?' + 1 agent sample copy':''}. Postage is included in the piece price.</p>`;}else if(p.method==='ship'){form+=`<p class="context-help">Send one printed batch to you. Individual recipients are not needed.</p>${input('Printed quantity','product.qty',p.qty,'type="number" min="25" max="5000" step="1"','Minimum 25 copies. Change the quantity to update your estimate.')}<div class="section-title"><h3>Ship to</h3><button class="text-btn" data-action="shipping">${p.shipAddress?'Edit address':'Add address'}</button></div>${p.shipAddress?`<div class="address-summary"><strong>${esc(p.shipAddress.name)}</strong><br>${esc(p.shipAddress.street)}${p.shipAddress.street2?`, ${esc(p.shipAddress.street2)}`:''}<br>${esc(p.shipAddress.city)}, ${esc(p.shipAddress.state)} ${esc(p.shipAddress.zip)}</div>`:''}<p class="tiny muted">Ground shipping · Estimated 3–5 business days after production</p>`;}else if(p.method==='pickup'){form+=`<p class="context-help">Collect your printed batch from a local office. No shipping charge.</p>${input('Printed quantity','product.qty',p.qty,'type="number" min="25" max="5000" step="1"','Minimum 25 copies.')}${select('Pickup location','product.pickup',p.pickup,[['cedar','Cedar Realty · South Austin office'],['downtown','Cedar Realty · Downtown office']])}${input('Preferred pickup date','product.pickupDate',p.pickupDate,'type="date" min="2026-11-06"')}<p class="tiny muted">${p.pickup==='downtown'?'600 Congress Avenue, Austin, TX 78701':'214 Barton Springs Road, Austin, TX 78704'}<br>Monday–Friday, 9:00 a.m.–5:00 p.m. We’ll confirm when it’s ready.</p>`;}else{form+=`<p class="context-help">Get a digital asset for your own use. No printing, postage, or shipping.</p>${select('File format','product.format',p.format,[['pdf','PDF · Print-ready document'],['jpg','JPG · Digital image']])}<div class="static-field">${icon('download')}<span>Digital delivery · No charge<br><small>Available after your order is approved.</small></span></div>`;}
if(p.method!=='download'){form+=`<details class="options-detail" ${p.optionsOpen?'open':''} data-options><summary>Paper & ${p.method==='mail'?'sample copy':'extras'} ${icon('down')}</summary><p class="option-summary">${p.paper==='premium'?'Premium uncoated':'100 lb matte'}${p.pdf?' · PDF included':''}${p.sample&&p.method==='mail'?' · 1 agent sample':''}</p><div class="options-body">${select('Paper','product.paper',p.paper,[['matte','100 lb matte · Included'],['premium','Premium uncoated · +$0.10 / piece'],['unavailable','Recycled satin · Temporarily unavailable']])}${p.paper==='unavailable'?`<div class="warning-inline">${icon('alert')}<span>Pricing is unavailable for recycled satin. Choose another paper to continue.</span></div>`:''}${check('Add a print-ready PDF · $5.00','product.pdf',p.pdf)}${p.method==='mail'?`${check('Send one sample copy to the agent','product.sample',p.sample,'Adds 1 printed piece to your order.')}${p.sample?(p.sampleAddress?`<div class="address-summary"><strong>Sample copy address</strong><br>${addressText(p.sampleAddress)}<br><button class="text-btn" data-action="sample-address">Edit address</button></div>`:`<div class="warning-inline">${icon('alert')}<div><p>Where should we send your sample copy?</p><button class="text-btn" data-action="sample-address">Add sample address</button></div></div>`):''}`:''}</div></details>`;}
if(ui.error)form+=`<p class="error" role="alert">${esc(ui.error)}</p>`;return form;}
function deliverySummary(){const id=currentId(),p=product(),cost=pricing(id),q=qty(id),error=deliveryError(id);return `<div class="support-heading">${catalog[id].name} summary</div><div class="small muted">${p.method==='mail'?'Mailed individually':p.method==='ship'?'Bulk batch · Ship to agent':p.method==='pickup'?'Bulk batch · Local pickup':'Digital download'}</div><div class="cost-details"><div class="summary-row"><span>${p.method==='download'?'Digital '+p.format.toUpperCase():q+' printed '+(id==='brochures'?'brochures':id==='postcards'?'postcards':'flyers')}</span><span>${money(cost.print)}</span></div>${p.method!=='download'?`<div class="summary-row"><span class="muted">${p.method==='mail'?'Mail preparation':p.method==='ship'?'Ground shipping':'Pickup'}</span><span>${money(cost.fulfillment)}</span></div>`:''}${cost.pdf?`<div class="summary-row"><span class="muted">PDF add-on</span><span>${money(cost.pdf)}</span></div>`:''}<div class="summary-row total"><span>Product total</span><strong>${p.paper==='unavailable'&&p.method!=='download'?'—':money(cost.total)}</strong></div></div><div class="tiny muted">Before estimated tax and credits</div>${p.method==='mail'?`<div class="quiet-note" style="margin-top:17px">${icon('users')}<span>${audienceCount()} recipients${p.sample?' + 1 agent sample':''}<br>${q} total printed pieces</span></div>`:''}<div class="delivery-proof-mini">${proof()}</div><div class="proof-meta">${p.reviewed?'Approved proof':'Proof review needed'} · ${p.template==='willow'?'The Willow Collection':'Modern Essentials'}</div><details class="cost-disclosure"><summary>How is this price calculated?</summary><p>${p.method==='download'?'Digital artwork is included at no charge.':`${q} × ${money(cost.unit+(p.paper==='premium'?.10:0))} per printed piece${p.method==='mail'?' (including postage), plus $4.50 mail preparation.':p.method==='ship'?', plus $6.00 ground shipping.':'. Pickup is free.'}${p.method==='mail'&&p.mailClass==='first'?' First Class adds $0.10 per piece.':''}${p.pdf?' The optional PDF adds $5.00.':''}`}</p></details>`;}
function deliveryStep(){const id=currentId(),last=state.active===state.selected.length-1;return `${panelTitle('Set up delivery','Choose how and where your '+catalog[id].name.toLowerCase()+' should go.',`<span class="small muted">Product ${state.active+1} of ${state.selected.length}</span>`)}${productTabs()}<div class="content-columns"><section class="form-column">${deliveryForm()}</section><aside class="support-column">${deliverySummary()}</aside></div>${footer(`<div class="footer-total">${catalog[id].name} · ${product().method==='download'?'Digital':qty(id)+' pieces'}<strong>${product().paper==='unavailable'&&product().method!=='download'?'Choose paper':money(pricing(id).total)}</strong></div>`,last?'Review order':'Save & next product','save-delivery')}`;}
function audienceStep(){const lists=state.lists.filter(l=>l.name.toLowerCase().includes(ui.listSearch.toLowerCase())),count=state.lists.filter(l=>ui.audienceDraft.includes(l.id)).reduce((a,b)=>a+b.count,0);return `${panelTitle('Choose your mailing lists','Select one or more audiences for your '+catalog[currentId()].singular+'.',btn(icon('plus')+' Create list','create-list'))}<div class="content-columns audience-columns"><section class="form-column"><div class="table-top"><div class="search-input">${icon('search')}<input aria-label="Search mailing lists" data-bind="ui.listSearch" value="${esc(ui.listSearch)}" placeholder="Search saved lists"></div><span class="tiny muted">${state.lists.length} saved lists</span></div><table class="saved-lists"><thead><tr><th aria-label="Select"></th><th>List name</th><th>Recipients</th><th>Created</th><th></th></tr></thead><tbody>${lists.map(l=>`<tr class="${ui.audienceDraft.includes(l.id)?'selected-row':''}"><td><input type="checkbox" aria-label="Select ${esc(l.name)}" data-list="${l.id}" ${ui.audienceDraft.includes(l.id)?'checked':''}></td><td><strong>${esc(l.name)}</strong><small>${l.type}</small></td><td>${l.count}</td><td class="tiny muted">${l.date}</td><td><button class="text-btn" data-action="edit-list" data-id="${l.id}">Edit</button></td></tr>`).join('')}</tbody></table>${!lists.length?'<div class="empty-state">No lists match your search.</div>':''}<div class="selection-tally"><strong>${count}</strong> recipients across ${ui.audienceDraft.length} ${ui.audienceDraft.length===1?'list':'lists'}</div></section><aside class="support-column"><div class="support-heading">Audience summary</div><div class="summary-row"><span>Selected recipients</span><strong>${count}</strong></div>${product().sample?'<div class="summary-row"><span class="muted">Agent sample copy</span><strong>+ 1</strong></div>':''}<div class="summary-row total"><span>Printed quantity</span><strong>${count+(product().sample?1:0)}</strong></div><p class="small muted">Your print quantity follows your selected audience. Adding a list updates the product price.</p><div class="quiet-note">${icon('mail')}<span>Each recipient receives one ${catalog[currentId()].singular}. Lists remain available for future orders.</span></div></aside></div>${footer('<span class="footer-note">These recipients apply to this product.</span>','Use selected lists','use-lists','audience-back',!count)}`;}
function createListStep(){return `${panelTitle('Create a mailing list','Choose where your recipients will come from.')}<div class="content-columns"><section class="form-column"><div class="create-grid">${[['radius','target','Radius','Find nearby homes around an address.'],['upload','upload','Upload','Start with a recipient CSV file.'],['street','pin','Street','Choose addresses along a street.'],['demographics','users','Demographics','Build an audience using household criteria.'],['crm','layers','CRM Import','Use contacts from a connected CRM.']].map(([id,ic,t,d])=>`<button class="source-card" data-action="list-source" data-id="${id}">${icon(ic)}<span><strong>${t}</strong><small>${d}</small></span></button>`).join('')}</div></section><aside class="support-column"><div class="support-heading">Start close to home</div><h3 style="font-size:14px;margin:0 0 10px">Introduce your new listing<br>to the neighborhood.</h3><p class="small muted">Radius targeting finds nearby homes, starting with the closest eligible addresses to your listing.</p><div class="quiet-note">${icon('target')}<span>Choose how many households to reach, preview the results, then add the list to your order.</span></div></aside></div>${footer('<span class="footer-note">Your selected lists are preserved.</span>','Set up radius list','radius','to-audience')}`;}
function mapArt(){const points=Array.from({length:ui.radius.preview?Math.min(50,Number(ui.radius.qty)):12},(_,i)=>{const angle=i*2.4,r=12+Math.sqrt(i)*14,x=240+Math.cos(angle)*r,y=166+Math.sin(angle)*r*.85;return `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3" fill="#648ca7" stroke="#fff" stroke-width="1.1"/>`;}).join('');return `<div class="map"><svg class="map-art" viewBox="0 0 480 350" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Illustrative map of nearby single-family homes around 128 Willow Lane"><rect width="480" height="350" fill="#edf0e8"/><path d="M330 0h150v130l-40-20-20-60-90 8zM0 248l75-36 31 79-60 59H0z" fill="#dbe5d3"/><path d="m421 0-44 102 41 99-26 149" stroke="#d2dfdf" stroke-width="19" fill="none"/><g stroke="#dce1d7" stroke-width="1">${Array.from({length:12},(_,i)=>`<path d="M${i*47+10} 0v350M0 ${i*40+9}h480"/>`).join('')}</g><g stroke="#d0d7cd" stroke-width="11">${[65,146,225,309,390].map(x=>`<path d="M${x} 0v350"/>`).join('')}${[70,150,230,310].map(y=>`<path d="M0 ${y}h480"/>`).join('')}</g><g stroke="#fffef9" stroke-width="8">${[65,146,225,309,390].map(x=>`<path d="M${x} 0v350"/>`).join('')}${[70,150,230,310].map(y=>`<path d="M0 ${y}h480"/>`).join('')}</g><path d="m0 274 480-85" stroke="#d8d9c9" stroke-width="21"/><path d="m0 274 480-85" stroke="#fff9e4" stroke-width="17"/><ellipse cx="240" cy="166" rx="133" ry="121" fill="#5d8db517" stroke="#7e9fb8" stroke-width="1.5" stroke-dasharray="5 4"/><g font-family="Arial,sans-serif" font-size="9" fill="#9aa494"><text x="156" y="139">WILLOW LANE</text><text x="13" y="61">W MARY ST</text><text x="322" y="300">SOUTH AUSTIN</text><text x="320" y="58">GILLIS PARK</text><text transform="translate(299 131) rotate(-90)">S 2ND STREET</text><text transform="translate(65 292) rotate(-10)">W OLTORF STREET</text></g>${points}<circle cx="240" cy="166" r="10" fill="#fff" stroke="#4e718b" stroke-width="1.5"/><path d="m240 151 7-5-2-8-5-3-5 3-2 8z" fill="#3d6584" transform="translate(0 20)"/><rect x="167" y="184" width="147" height="25" rx="3" fill="#fff" stroke="#cdd7de"/><text x="240" y="200" text-anchor="middle" fill="#587183" font-family="Arial" font-size="10">${esc(ui.radius.address.slice(0,28))}</text></svg><div class="map-label">Austin, TX ${esc(ui.radius.zip)}</div><div class="map-legend"><i></i> ${ui.radius.preview?ui.radius.qty:'Nearby'} ${ui.radius.homes==='single'?'single-family':'residential'} addresses &nbsp;·&nbsp; Illustrative map</div></div>`;}
function radiusStep(){const r=ui.radius;return `${panelTitle('Find nearby recipients','Create a radius list centered on your property.')}<div class="content-columns radius-columns"><section class="form-column">${input('Center address','radius.address',r.address)}<div class="field-row">${input('ZIP code','radius.zip',r.zip,'inputmode="numeric" maxlength="5"')}${input('Recipients','radius.qty',r.qty,'type="number" min="10" max="500" step="1"')}</div>${select('Property type','radius.homes',r.homes,[['single','Single-family homes'],['multi','Multi-family homes'],['all','All residential homes']])}${check('Exclude 128 Willow Lane','radius.exclude',r.exclude,'The listing itself will not receive a mailing.')}<div class="divider-line"></div>${input('List name','radius.name',r.name||'Willow Lane · Nearby 50','maxlength="60"')}<p class="context-help">Start with the closest eligible addresses and expand outward until your quantity is reached.</p>${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}${r.preview?`<div class="success-inline">${icon('check')}${r.qty} eligible addresses found</div>`:''}</section><aside class="support-column">${mapArt()}${r.preview?`<div class="radius-results"><strong>${r.qty} ${r.homes==='single'?'single-family':r.homes==='multi'?'multi-family':'residential'} addresses · approximately 0.4 mi</strong><p>${r.exclude?'Target property excluded.':'Target property included.'} Addresses shown are fictional.</p><table class="recipient-preview"><tbody>${['132 Willow Lane','140 Willow Lane','206 Oak Meadow Drive'].map((s,i)=>`<tr><td>${r.homes==='multi'&&i===2?'206 Oak Meadow Drive, Apt 2':s}</td><td>Austin, TX 78704</td></tr>`).join('')}</tbody></table></div>`:`<p class="small muted" style="margin-top:15px">Preview your audience before adding it to your order.</p>`}</aside></div>${footer(`<span class="footer-note">${r.preview?r.qty+' recipients ready to add':'Your order has not changed yet.'}</span>`,r.preview?'Add list to order':'Preview addresses',r.preview?'confirm-radius':'preview-radius','create-list')}`;}
function reviewNav(){return `<nav class="review-progress" aria-label="Review stages">${['Products','Credits','Payment & approval'].map((n,i)=>`${i?icon('chevron'):''}<button data-action="review-tab" data-index="${i}" class="${state.reviewStage===i?'active':''}" ${state.reviewStage===i?'aria-current="step"':''}>${i+1}. ${n}</button>`).join('')}</nav>`;}
function orderSummary(){const t=totals();return `<div class="support-heading">Order summary</div><div class="summary-subtitle">128 Willow Lane · ${state.selected.length} products</div><div class="cost-details"><div class="summary-row"><span>Subtotal</span><span>${money(t.sub)}</span></div><div class="summary-row"><span class="muted">Estimated tax</span><span>${money(t.t)}</span></div>${t.promo?`<div class="summary-row"><span class="muted">Promo · LISTING10</span><span>−${money(t.promo)}</span></div>`:''}${t.store?`<div class="summary-row"><span class="muted">Store credit</span><span>−${money(t.store)}</span></div>`:''}${t.ad?`<div class="summary-row"><span class="muted">Ad budget</span><span>−${money(t.ad)}</span></div>`:''}<div class="summary-row total"><span>${state.reviewStage===2?'Amount to allocate':'Remaining balance'}</span><strong>${money(t.balance)}</strong></div></div>${state.reviewStage===2?`<div class="divider-line"></div><div class="section-title"><h3>Billing allocation</h3></div>${state.payment==='split'?`<div class="summary-row small"><span class="muted">Visa ···· 4242</span><span>${money(Number(state.split)||0)}</span></div><div class="summary-row small"><span class="muted">Mastercard ···· 1881</span><span>${money(Math.max(0,t.balance-(Number(state.split)||0)))}</span></div>`:`<div class="summary-row small"><span class="muted">${state.payment==='corporate'?'Cedar Realty account':state.payment==='new'?esc(state.cardLabel):'Visa ···· 4242'}</span><span>${money(t.balance)}</span></div>`}<div class="summary-row small"><strong>Unallocated balance</strong><strong>${state.payment==='split'&&(Number(state.split)<0||Number(state.split)>t.balance)?money(t.balance):money(0)}</strong></div><div class="approval-note">${state.orderMode==='approval'?'Your order will be sent to the marketing team for review. Billing is authorized only after approval.':'Your order will enter the print queue immediately.'}</div>`:`<div class="quiet-note">${icon('info')}<span>Printing, postage, and fulfillment charges are included. Review credits before choosing payment.</span></div>`}<details class="cost-disclosure"><summary>View product breakdown</summary>${state.selected.map(id=>`<div class="summary-row"><span>${catalog[id].name} · ${qty(id)} ${state.products[id].method==='download'?'file':'pieces'}</span><span>${money(pricing(id).total)}</span></div>`).join('')}</details>`;}
function reviewProducts(){return `${reviewNav()}<div class="review-strip"><span>${state.selected.length} products ready for review</span><span class="status-label">${icon('check')}Listing details match</span></div>${state.selected.map((id,i)=>{const p=state.products[id];return `<div class="review-product"><div class="product-art">${miniArt(id)}</div><div class="review-info"><h3>${catalog[id].name}</h3><p>${p.template==='willow'?'The Willow Collection':'Modern Essentials'}</p><p>${p.method==='mail'?`${qty(id)} pieces · ${audienceCount(id)} recipients${p.sample?' + 1 sample':''}`:p.method==='download'?p.format.toUpperCase()+' · Digital download':`${qty(id)} copies · ${p.method==='ship'?'Ship to Jordan Ellis':'Local pickup'}`}</p><span class="status-label ${ready(id)?'ready':''}">${icon(ready(id)?'check':'alert')}${ready(id)?'Proof approved · Delivery complete':'Configuration needs attention'}</span></div><div class="review-price">${money(pricing(id).total)}<button class="text-btn" data-action="edit-product" data-index="${i}">Review / edit</button></div></div>`;}).join('')}<p class="small muted">Check each product’s design and delivery. Your credits and payment come next.</p>${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}`;}
function reviewCredits(){const t=totals();return `${reviewNav()}<h3 class="section-title">Apply credits to this order</h3><p class="context-help">Choose the balances you’d like to use. Any amount left over will be billed at the next step.</p><div class="credit-card">${icon('tag')}<div class="credit-info"><strong>Promo code</strong>${state.credits.promo?`<p>LISTING10 applied</p><button class="text-btn" data-action="remove-promo" style="margin-top:6px">Remove code</button>`:ui.promoOpen?`<div class="promo-form"><input aria-label="Promo code" data-bind="ui.promoCode" placeholder="Enter code" value="${esc(ui.promoCode)}">${btn('Apply','apply-promo')}</div><p>Try LISTING10 for $10 off.</p>${ui.error?`<div class="error">${esc(ui.error)}</div>`:''}`:`<p>Have a code?</p><button class="text-btn" data-action="show-promo" style="margin-top:7px">Add promo code</button>`}</div>${state.credits.promo?`<span class="credit-applied">−${money(t.promo)}</span>`:''}</div><div class="credit-card">${icon('wallet')}<div class="credit-info"><strong>Store credit</strong><p>$20.00 available · ${state.credits.store?money(20-t.store):'$20.00'} after this order</p></div><label class="check-row"><input type="checkbox" aria-label="Apply store credit" data-bind="credits.store" ${state.credits.store?'checked':''}><span>${state.credits.store?'Applied':'Use $20.00'}</span></label></div><div class="credit-card">${icon('megaphone')}<div class="credit-info"><strong>Marketing ad budget</strong><p>$30.00 available · ${state.credits.ad?money(30-t.ad):'$30.00'} after this order</p></div><label class="check-row"><input type="checkbox" aria-label="Apply ad budget" data-bind="credits.ad" ${state.credits.ad?'checked':''}><span>${state.credits.ad?'Applied':'Use $30.00'}</span></label></div><p class="tiny muted">Available balances and credit eligibility are illustrative for this order.</p>`;}
function reviewPayment(){const t=totals();return `${reviewNav()}<div class="section-title"><h3>Payment method</h3><button class="text-btn" data-action="add-card">${icon('plus')} Add a card</button></div>${[['visa','card','Visa ending in 4242','Expires 08/28'],...(state.cardAdded?[['new','card',state.cardLabel,'Added for this simulated order']]:[]),['corporate','building','Cedar Realty corporate account','Marketing department · Account CR-204'],['split','card','Split between two saved cards','Set the amount for each card']].map(([v,ic,title,sub])=>`<label class="payment-choice ${state.payment===v?'active':''}"><input type="radio" name="payment" value="${v}" data-bind="payment" ${state.payment===v?'checked':''}>${icon(ic)}<span>${esc(title)}<small>${sub}</small></span>${v==='visa'?'<b class="card-wordmark">VISA</b>':''}</label>`).join('')}${state.payment==='corporate'?`<div class="billing-detail">${input('Organization','readonly','Cedar Realty · South Austin','readonly')}${input('Cost center (required)','state.costCenter',state.costCenter,'placeholder="e.g. AUSTIN-MKT"')}<label class="field"><span>Billing comments (required)</span><textarea data-bind="state.billingComments" placeholder="What is this order for?">${esc(state.billingComments)}</textarea></label></div>`:state.payment==='split'?`<div class="billing-detail"><div class="split-allocation"><span>Visa ···· 4242</span><input aria-label="Visa allocation" data-bind="state.split" type="number" min="0" max="${t.balance}" step="0.01" value="${state.split}"></div><div class="split-allocation"><span>Mastercard ···· 1881</span><strong>${money(Math.max(0,t.balance-(Number(state.split)||0)))}</strong></div><div class="allocation-total"><span>Total allocated</span><strong>${money(t.balance)}</strong></div><p class="tiny muted">The second card covers the remaining balance automatically.</p></div>`:''}<div class="divider-line"></div>${select('Order routing','state.orderMode',state.orderMode,[['approval','Submit for marketing approval'],['direct','Place order directly · Admin permission']])}<div class="acknowledgment">${check('<strong>I have reviewed the proofs and order details.</strong>','state.ack',state.ack,'I accept responsibility for the artwork, recipient lists, quantities, and delivery details.')}</div>${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}<div class="simulated-note">${icon('lock')}Simulation only. No payment is processed or order transmitted.</div>`;}
function reviewStep(){const stage=state.reviewStage;return `${panelTitle(stage===0?'Review your products':stage===1?'Credits & savings':'Payment & approval',stage===0?'Make sure everything looks right before moving on.':stage===1?'Use the credits available to this listing.':'Choose how to cover the remaining balance.')}<div class="content-columns"><section class="form-column">${stage===0?reviewProducts():stage===1?reviewCredits():reviewPayment()}</section><aside class="support-column">${orderSummary()}</aside></div>${footer(`<div class="footer-total">${stage===2?'To be allocated':'Remaining balance'}<strong>${money(totals().balance)}</strong></div>`,stage===0?'Continue to credits':stage===1?'Continue to payment':state.orderMode==='approval'?'Submit for Approval':'Place simulated order',stage===2?'submit-order':'next-review','review-back')}`;}
function successStep(){const t=totals();return `<div class="success-screen"><div class="success-circle">${icon('check')}</div><h2>${state.orderMode==='approval'?'Your order is ready for approval.':'Your order has been placed.'}</h2><p>${state.orderMode==='approval'?'The Cedar Realty marketing team can now review your materials. You’ll receive an update when your order is approved.':'Your printed materials are ready for the next step.'} This is a simulated confirmation.</p><span class="status-pill">${icon(state.orderMode==='approval'?'clock':'check')}${state.orderMode==='approval'?'Awaiting approval':'Order received'} · APM-10482</span><div class="confirmation"><div class="section-title"><h3>128 Willow Lane</h3><span class="tiny muted">Austin, TX 78704</span></div>${state.selected.map(id=>`<div class="summary-row"><span>${catalog[id].name} · ${qty(id)} ${state.products[id].method==='download'?'file':'pieces'} · ${state.products[id].method}</span><span>${money(pricing(id).total)}</span></div>`).join('')}<div class="summary-row total"><span>${state.orderMode==='approval'?'Amount after approval':'Simulated payment'}</span><strong>${money(t.balance)}</strong></div><div class="small muted">${state.payment==='corporate'?'Cedar Realty corporate billing':state.payment==='split'?'Two saved cards':state.payment==='new'?esc(state.cardLabel):'Visa ending in 4242'} · No charge has been made.</div></div><div class="success-actions">${btn('View order details','confirmation-details')}${btn('Start another order '+icon('arrow'),'new-order','primary')}</div></div>`;}
function addressFields(){const a=ui.sampleDraft;return `<button class="text-btn" data-action="use-agent-address" style="margin-bottom:20px">${icon('users')} Use Jordan’s office address</button>${input('Name / company','address.name',a.name||'','autocomplete="off"')}${input('Street address','address.street',a.street||'','autocomplete="off"')}${input('Address line 2 (optional)','address.street2',a.street2||'','autocomplete="off"')}<div class="field-row">${input('City','address.city',a.city||'')}${input('State','address.state',a.state||'','maxlength="2"')}</div>${input('ZIP code','address.zip',a.zip||'','inputmode="numeric" maxlength="10"')}${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}`;}
function drawerContent(){let title='',sub='',body='',actions='',wide=false;const p=product(),id=currentId();switch(ui.drawer){
case 'templates':title='Choose a template';sub=catalog[id].name+' · Property marketing';body=`<div class="template-grid">${[['willow','The Willow Collection','Warm white · Classic'],['modern','Modern Essentials','Slate · Contemporary']].map(([v,t,s])=>`<button class="template-choice ${ui.templateChoice===v?'selected':''}" data-action="choose-template" data-id="${v}" aria-pressed="${ui.templateChoice===v}"><div class="template-thumb" style="${v==='modern'?'background:#dce4eb;':''}">${miniArt('flyers')}</div><strong>${t}</strong><span>${s}</span></button>`).join('')}</div><div class="divider-line"></div><p class="small muted">Each template uses the same listing and agent information. Your text and photo choices are preserved.</p>`;actions=btn('Use template','save-template','primary');break;
case 'edit-content':title='Edit text & photo';sub='A focused update to your selected template';body=`${input('Headline','temp.headline',ui.temp.headline,'maxlength="55"')}<label class="field"><span>Property description</span><textarea data-bind="temp.description" maxlength="220">${esc(ui.temp.description)}</textarea><small>Keep the description brief so it fits comfortably in the template.</small></label><div class="section-title"><h3>Main photo</h3></div><div class="photo-options">${[['house','Property exterior'],['interior','Living area']].map(([v,t])=>`<button class="${ui.temp.photo===v?'selected':''}" data-action="choose-photo" data-id="${v}" aria-pressed="${ui.temp.photo===v}"><img src="assets/willow-${v}.jpg" alt="${t}">${t}</button>`).join('')}</div>${ui.error?`<p class="error" role="alert">${esc(ui.error)}</p>`:''}`;actions=btn('Save changes','save-content','primary');break;
case 'qr':title=p.qr?'Edit QR code':'Add a QR code';sub='Link your printed materials to the listing online.';body=`${input('Destination URL','ui.qrValue',ui.qrValue,`type="url" placeholder="https://..." ${ui.qrStatus==='invalid'?'class="invalid" aria-invalid="true"':''}`,'Enter the full listing URL, including https://.')}${btn(icon('qr')+' Validate & generate','generate-qr')}${ui.qrStatus==='invalid'?`<p class="error" role="alert">Enter a complete URL, such as https://cedarrealty.example/willow.</p>`:ui.qrStatus==='required'?'<p class="error" role="alert">A destination URL is required.</p>':ui.qrStatus==='unverified'?`<div class="warning-inline">${icon('alert')}<div><p>We couldn’t validate this listing link.</p><span>Check the address and try again, or continue if you’ve verified it yourself.</span></div></div>${check('Use this URL without validation','ui.qrOverride',ui.qrOverride,'I understand that I am responsible for checking the link.')}`:ui.qrStatus==='ready'?`<div class="success-inline">${icon('check')}Link looks good. QR code is ready to save.</div>`:''}${['ready','unverified'].includes(ui.qrStatus)?`<div class="qr-pattern">${qrArt()}</div><p class="tiny muted" style="text-align:center">Illustrative QR placement · Validation is simulated</p>`:`<div class="qr-placeholder">${icon('qr')}Your QR preview will appear here</div>`}${p.qr?btn(icon('trash')+' Delete QR code','delete-qr','danger'):''}`;actions=btn('Save QR code','save-qr','primary',!['ready','unverified'].includes(ui.qrStatus)||(ui.qrStatus==='unverified'&&!ui.qrOverride)?'disabled':'');break;
case 'proof':title='Review your proof';sub=catalog[id].name+' · 128 Willow Lane';wide=true;body=`<div class="proof-large">${proof()}</div><p class="small muted" style="margin-top:17px">Check the property details, photo, and contact information. Approving saves this version of the design.</p>`;actions=btn(icon('check')+' Approve this proof','approve-proof','primary');break;
case 'sample-address':case 'shipping':title=ui.drawer==='sample-address'?'Sample copy address':'Shipping address';sub=ui.drawer==='sample-address'?'One additional copy will be mailed to this address.':'Your printed batch will be delivered to this address.';body=addressFields();actions=btn('Save address','save-address','primary');break;
case 'listing':title='Choose listing / event';sub='This context will apply to every product in your order.';body=`<img src="assets/willow-house.jpg" alt="128 Willow Lane" class="property-photo" style="height:170px;margin-bottom:20px">${input('Property','readonly','128 Willow Lane, Austin, TX 78704','readonly')}${select('Marketing event','temp.event',ui.temp.event,[['new','New Listing · November 5, 2026'],['open','Open House · November 8, 2026']])}<p class="small muted">Agent: Jordan Ellis · Cedar Realty</p>`;actions=btn('Use listing event','save-listing','primary');break;
case 'edit-list':{const l=state.lists.find(x=>x.id===ui.listEditId);title='Edit mailing list';sub=l.type+' · '+l.count+' recipients';body=`${input('List name','temp.listName',ui.temp.listName,'maxlength="60"')}<div class="list-edit-meta">Created ${l.date} · ${l.count} addresses</div><h3 class="section-title">Recipient preview</h3><table class="recipient-preview"><tbody>${['132 Willow Lane','140 Willow Lane','206 Oak Meadow Drive'].map(s=>`<tr><td>${s}</td><td>Austin, TX 78704</td></tr>`).join('')}</tbody></table><p class="tiny muted">Fictional addresses shown for this prototype.</p>${ui.error?`<p class="error">${esc(ui.error)}</p>`:''}`;actions=btn('Save list','save-list-edit','primary');break;}
case 'source':{const s=ui.source,names={upload:'Upload a list',street:'Build a street list',demographics:'Choose demographics',crm:'Import from CRM'};title=names[s];sub='Create a saved audience for this order';body=`${input('List name','temp.sourceName',ui.temp.sourceName)}${s==='upload'?`<label class="field"><span>Recipient file</span><input type="file" accept=".csv" data-bind="temp.upload"><small>CSV with name, street, city, state, and ZIP.</small></label>`:s==='street'?input('Street address','temp.sourceAddress',ui.temp.sourceAddress||'Willow Lane, Austin, TX 78704'):s==='demographics'?select('Household type','temp.sourceFilter',ui.temp.sourceFilter||'owner',[['owner','Owner-occupied homes'],['all','All households']]):select('CRM','temp.sourceCRM',ui.temp.sourceCRM||'cedar',[['cedar','Cedar Realty · Example contacts'],['other','Other CRM · Example contacts']])}${input('Recipient quantity','temp.sourceCount',ui.temp.sourceCount,'type="number" min="1" max="5000"')}<div class="quiet-note">${icon('info')}<span>This is an illustrative setup proposal. Import processing and audience matching are simulated; no files or contacts leave this browser.</span></div>${ui.error?`<p class="error">${esc(ui.error)}</p>`:''}`;actions=btn('Create example list','save-source','primary');break;}
case 'catalog':{const c=catalog[ui.temp.catalog];title=c.name;sub='Cedar Realty · Marketing catalog';body=`<div class="static-field" style="padding:25px;gap:20px">${miniArt(ui.temp.catalog)}<span><strong>${c.name}${c.free?' · Free':''}</strong><br><small>${c.desc}</small></span></div><h3 class="section-title">${ui.temp.catalog==='facebook'?'A local campaign for your listing':'A digital companion to your print order'}</h3><p class="context-help">${ui.temp.catalog==='facebook'?'Promote your property to an online audience with listing artwork and a dedicated campaign budget.':'Use your listing photography, property details, and Cedar Realty branding in a digital format.'}</p><div class="summary-row"><span class="muted">Listing</span><span>128 Willow Lane</span></div><div class="summary-row"><span class="muted">${ui.temp.catalog==='facebook'?'Setup':'Artwork'}</span><span>${ui.temp.catalog==='facebook'?'Campaign options':'Included at no charge'}</span></div><p class="tiny muted" style="margin-top:24px">This prototype develops the print ordering journey. Digital products are represented here at catalog level.</p>`;actions=btn('Back to products','close-drawer','primary');break;}
case 'add-card':title='Add a card';sub='Simulated payment method · Use fictional details only';body=`<div class="static-field">${icon('lock')}<span>No real card details needed.<br><small>Choose an example card for this prototype.</small></span></div>${input('Name on card','card.name',ui.cardDraft.name||'Jordan Ellis')}${select('Example card','card.type',ui.cardDraft.type||'mastercard',[['mastercard','Mastercard ending in 5556'],['visa','Visa ending in 1008']])}<p class="small muted">Adding this card makes it available for this order. No payment information is sent or stored.</p>`;actions=btn('Use example card','save-card','primary');break;
case 'orders':case 'confirmation-details':title='Your orders';sub='Cedar Realty · Jordan Ellis';body=`<div class="review-product"><div class="product-art">${miniArt('flyers')}</div><div class="review-info"><h3>128 Willow Lane</h3><p>${state.selected.length} products · ${state.submitted?'APM-10482':'Draft order'}</p><span class="status-label ${state.submitted?'ready':''}">${icon(state.submitted?'check':'clock')}${state.submitted?(state.orderMode==='approval'?'Awaiting marketing approval':'Order received'):'Saved in this browser'}</span></div><strong class="small">${money(totals().balance)}</strong></div><div class="divider-line"></div>${state.selected.map(id=>`<div class="summary-row"><span>${catalog[id].name} · ${qty(id)} pieces</span><span>${money(pricing(id).total)}</span></div>`).join('')}<p class="tiny muted">All ordering and billing in this prototype is simulated.</p>`;actions=btn(state.submitted?'Close details':'Continue draft','close-drawer','primary');break;
case 'account':title='Jordan Ellis';sub='Cedar Realty · South Austin';body=`<div class="static-field">${icon('users')}<span><strong>Administrator</strong><br><small>Can submit for approval or place an order directly.</small></span></div>${input('Email','readonly','jordan@cedarrealty.example','readonly')}${input('Office','readonly','Cedar Realty · South Austin','readonly')}<h3 class="section-title">Saved template preferences</h3>${state.selected.map(id=>`<div class="summary-row"><span>${catalog[id].name}</span><span class="muted">${state.products[id].defaultTemplate?(state.products[id].template==='willow'?'The Willow Collection':'Modern Essentials'):'No default saved'}</span></div>`).join('')}`;actions=btn('Done','close-drawer','primary');break;
case 'activity':title='Order activity';sub='Your current draft';body=`<div class="summary-item">${icon('check')}<span>Draft saved locally<small>Your listing, products, and delivery choices are preserved.</small></span></div>${state.selected.map(id=>`<div class="summary-item">${icon(state.products[id].reviewed?'check':'clock')}<span>${catalog[id].name}<small>${state.products[id].reviewed?'Proof approved':'Proof review pending'}</small></span></div>`).join('')}`;actions=btn('Done','close-drawer','primary');break;
default:title='Ordering with APM';sub='One listing. A focused path to your marketing materials.';body=`${[['1. Choose your products','Select flyers, brochures, or postcards for the same property.'],['2. Customize & approve','Choose a template and review each proof.'],['3. Set up delivery','Ship a batch to yourself or mail each piece to a recipient.'],['4. Review & submit','Apply credits, allocate the balance, and send for approval.']].map(([h,t])=>`<h3 class="section-title" style="margin-top:20px">${h}</h3><p class="context-help">${t}</p>`).join('')}<div class="quiet-note">${icon('info')}<span>All people, listing details, audiences, and prices are fictional. Nothing is sent to a real service.</span></div>`;actions=btn('Got it','close-drawer','primary');
}return `<div class="overlay" data-overlay><section class="drawer ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header class="drawer-head"><div><h2 id="drawer-title">${title}</h2><p>${sub}</p></div><button class="close-btn" data-action="close-drawer" aria-label="Close panel">${icon('close')}</button></header><div class="drawer-body">${body}</div><footer class="drawer-footer">${btn('Cancel','close-drawer','ghost')}${actions}</footer></section></div>`;}
function render(){const id=currentId();let content=state.submitted?successStep():ui.view==='audience'?audienceStep():ui.view==='create-list'?createListStep():ui.view==='radius'?radiusStep():state.step===0?catalogStep():state.step===1?designStep():state.step===2?deliveryStep():reviewStep();$('#app').innerHTML=`<div class="app-shell" ${ui.drawer?'inert':''}><header class="topbar"><div class="brandmark">${icon('layers')}</div><span class="brand">APM</span><span class="brand-desc">AGENT PROPERTY<br>MARKETING</span><div class="top-right"><span class="role">ADMIN</span><button class="top-icon" data-action="activity" aria-label="Order activity">${icon('bell')}</button><span class="divider"></span><button class="top-user" data-action="account"><span class="avatar">JE</span><span class="user-name">Jordan Ellis</span>${icon('down')}</button></div></header><nav class="rail" aria-label="Global navigation"><button data-action="orders" title="Workspace">${icon('grid')}</button><button data-action="home" class="active" title="Marketing orders" aria-label="Marketing orders">${icon('bag')}</button><button data-action="audience-nav" title="Audiences" aria-label="Audiences">${icon('users')}</button><button data-action="account" title="Account settings" aria-label="Account settings">${icon('settings')}</button></nav><aside class="sidebar"><div class="workspace-label"><span class="square">C</span>Cedar Realty</div><div class="nav-label">Marketing</div><button class="${!ui.view?'selected':''}" data-action="home">${icon('plus')}Create order</button><button data-action="orders">${icon('bag')}Orders</button><div class="nav-spacer"></div><div class="nav-label">Library</div><button class="${ui.view==='audience'?'selected':''}" data-action="audience-nav">${icon('users')}Mailing lists</button><button data-action="templates-nav">${icon('layers')}Templates</button><div class="nav-spacer"></div><button data-action="help">${icon('help')}Help & support</button><div class="side-bottom"><strong>Cedar Realty</strong>South Austin office<br>Marketing workspace</div></aside><main class="main"><div class="breadcrumb"><span>Marketing</span>${icon('chevron')}<span>${state.submitted?'Order APM-10482':'Create order'}</span></div><div class="page-heading"><div><h1>${state.submitted?'Order submitted':'Create marketing order'}</h1><p>${state.submitted?'Your listing materials, all in one place.':'Everything you need to bring your listing to market.'}</p></div><span class="saved">${icon('check')}All changes saved</span></div><div class="listing-bar"><img src="assets/willow-house.jpg" alt="128 Willow Lane listing"><div><div class="listing-address">128 Willow Lane</div><div class="listing-secondary"><span>Austin, TX 78704</span><span class="dot"></span><span>${state.event==='new'?'Nov 5, 2026':'Nov 8, 2026'}</span><span class="dot agent-context"></span><span class="agent-context">Jordan Ellis · Cedar Realty</span></div></div><span class="event-chip">${state.event==='new'?'New Listing':'Open House'}</span>${!state.submitted?btn('Change listing','listing','ghost'):''}</div><section class="panel" aria-label="Marketing order workflow">${!state.submitted?wizard():''}${content}</section><footer class="page-foot"><span>APM · Cedar Realty marketing workspace</span><button class="text-btn" data-action="help">Need help with your order?</button></footer></main></div>${ui.drawer?drawerContent():''}`;save();if(ui.drawer)requestAnimationFrame(()=>{$('.drawer .close-btn')?.focus({preventScroll:true});});}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3100);}
function openDrawer(name){lastFocus=document.activeElement;ui.error='';ui.drawer=name;render();}
function closeDrawer(){ui.drawer='';ui.error='';render();if(lastFocus?.dataset.action){const candidate=$(`[data-action="${lastFocus.dataset.action}"]`);candidate?.focus({preventScroll:true});}}
function go(step){state.step=step;ui.view='';ui.error='';render();window.scrollTo({top:0,behavior:'instant'});}
function beginAudience(){ui.audienceDraft=[...(state.listSelections[currentId()]||[])];ui.listSearch='';ui.view='audience';ui.error='';render();window.scrollTo({top:0,behavior:'instant'});}
function handleAction(action,el){const id=el?.dataset.id,index=Number(el?.dataset.index);ui.error='';switch(action){
case 'select-product':if(catalog[id].digital){ui.temp={catalog:id};openDrawer('catalog');return;}if(state.selected.includes(id)){state.selected=state.selected.filter(x=>x!==id);}else state.selected.push(id);state.active=0;break;
case 'to-design':state.active=0;go(1);return;
case 'step':if(index===0||index<=state.step){state.active=0;go(index);}return;
case 'product-tab':state.active=index;break;
case 'back':if(state.active>0)state.active--;else{state.active=0;go(Math.max(0,state.step-1));return;}break;
case 'approve-design':if(!product().headline.trim()){ui.error='Add a headline before approving your proof.';break;}product().reviewed=true;if(state.active<state.selected.length-1){state.active++;render();toast('Proof approved. Continue with your next product.');return;}const unreviewed=state.selected.findIndex(id=>!state.products[id].reviewed);if(unreviewed!==-1){state.active=unreviewed;render();toast('Review each product proof before choosing delivery.');return;}state.active=0;go(2);return;
case 'templates-nav':if(state.submitted){toast('Start a new order to choose a template.');return;}case 'templates':ui.templateChoice=product().template;openDrawer('templates');return;
case 'choose-template':ui.templateChoice=id;break;
case 'save-template':product().template=ui.templateChoice;product().reviewed=false;closeDrawer();toast('Template updated. Review the new proof.');return;
case 'edit-content':ui.temp={headline:product().headline,description:product().description,photo:product().photo};openDrawer('edit-content');return;
case 'choose-photo':ui.temp.photo=id;break;
case 'save-content':if(!ui.temp.headline.trim()){ui.error='Enter a headline for this design.';break;}Object.assign(product(),ui.temp,{reviewed:false});closeDrawer();toast('Design changes saved. Review your updated proof.');return;
case 'qr':ui.qrValue=product().qr||'https://cedarrealty.example/listing/willow-lane-old';ui.qrStatus=product().qr?'ready':'';ui.qrOverride=false;openDrawer('qr');return;
case 'generate-qr':if(!ui.qrValue.trim()){ui.qrStatus='required';break;}try{const url=new URL(ui.qrValue);if(!['https:','http:'].includes(url.protocol)||!url.hostname.includes('.'))throw new Error();ui.qrStatus=/old|invalid|broken|unavailable|not-found/i.test(ui.qrValue)?'unverified':'ready';}catch{ui.qrStatus='invalid';}break;
case 'save-qr':if(ui.qrStatus!=='ready'&&!(ui.qrStatus==='unverified'&&ui.qrOverride))return;product().qr=ui.qrValue;product().reviewed=false;closeDrawer();toast('QR code saved to the design.');return;
case 'delete-qr':product().qr='';product().reviewed=false;closeDrawer();toast('QR code removed from this design.');return;
case 'proof':openDrawer('proof');return;
case 'approve-proof':if(!product().headline.trim()){ui.error='Enter a headline before approving.';closeDrawer();return;}product().reviewed=true;closeDrawer();toast('Proof approved.');return;
case 'method':product().method=id;break;
case 'audience':case 'audience-nav':if(state.submitted){toast('Start a new order to manage mailing lists.');return;}beginAudience();return;
case 'audience-back':ui.view='';break;
case 'create-list':ui.view='create-list';break;
case 'to-audience':ui.view='audience';break;
case 'list-source':if(id==='radius'){ui.view='radius';ui.radius.preview=false;}else{ui.source=id;ui.temp={sourceName:id==='crm'?'Cedar Realty contacts':id==='street'?'Willow Lane street list':id==='demographics'?'Austin homeowners':'Uploaded recipients',sourceCount:id==='crm'?42:25};openDrawer('source');return;}break;
case 'radius':ui.view='radius';ui.radius.preview=false;break;
case 'preview-radius':{const r=ui.radius;if(!r.address.trim()||!/^\d{5}$/.test(r.zip)){ui.error='Enter a center address and a 5-digit ZIP code.';break;}if(!Number.isInteger(Number(r.qty))||r.qty<10||r.qty>500){ui.error='Choose between 10 and 500 whole recipient addresses.';break;}r.preview=true;break;}
case 'confirm-radius':{const r=ui.radius;if(!r.preview)return;const list={id:'radius-'+Date.now(),name:r.name?.trim()||`Willow Lane · Nearby ${r.qty}`,count:Number(r.qty),date:'Nov 2, 2026',type:'Radius · '+(r.homes==='single'?'Single-family':r.homes==='multi'?'Multi-family':'All residential')};state.lists.push(list);ui.audienceDraft.push(list.id);ui.view='audience';render();toast(`${list.count} nearby addresses added to your selected lists.`);return;}
case 'use-lists':state.listSelections[currentId()]=[...ui.audienceDraft];ui.view='';render();toast(`${audienceCount()} recipients selected. Product quantity updated.`);return;
case 'edit-list':ui.listEditId=id;ui.temp={listName:state.lists.find(x=>x.id===id).name};openDrawer('edit-list');return;
case 'save-list-edit':if(!ui.temp.listName.trim()){ui.error='Give this list a name.';break;}state.lists.find(l=>l.id===ui.listEditId).name=ui.temp.listName.trim();closeDrawer();toast('Mailing list updated.');return;
case 'save-source':if(!ui.temp.sourceName.trim()||!Number.isInteger(Number(ui.temp.sourceCount))||ui.temp.sourceCount<1||ui.temp.sourceCount>5000){ui.error='Enter a list name and a quantity from 1 to 5,000.';break;}if(ui.source==='upload'&&!ui.temp.upload){ui.error='Choose a CSV file to preview this example import.';break;}const newList={id:'source-'+Date.now(),name:ui.temp.sourceName.trim(),count:Number(ui.temp.sourceCount),date:'Nov 2, 2026',type:{upload:'Upload',crm:'CRM import',street:'Street',demographics:'Demographics'}[ui.source]};state.lists.push(newList);ui.audienceDraft.push(newList.id);ui.view='audience';closeDrawer();toast('Example audience saved and selected.');return;
case 'sample-address':case 'shipping':ui.sampleDraft={...(action==='shipping'?product().shipAddress:product().sampleAddress)||{}};openDrawer(action);return;
case 'use-agent-address':ui.sampleDraft={name:'Jordan Ellis · Cedar Realty',street:'214 Barton Springs Road',street2:'Suite 200',city:'Austin',state:'TX',zip:'78704'};break;
case 'save-address':{const a=ui.sampleDraft;if(!a.name?.trim()||!a.street?.trim()||!a.city?.trim()||!a.state?.trim()||!/^\d{5}(-\d{4})?$/.test(a.zip||'')){ui.error='Enter a name, street, city, state, and valid ZIP code.';break;}if(!/^[A-Za-z]{2}$/.test(a.state)){ui.error='Use a two-letter state abbreviation, such as TX.';break;}a.state=a.state.toUpperCase();product()[ui.drawer==='shipping'?'shipAddress':'sampleAddress']={...a};closeDrawer();toast('Address saved. Delivery is ready to continue.');return;}
case 'save-delivery':{const error=deliveryError(currentId());if(error){ui.error=error;if(product().sample&&!product().sampleAddress)product().optionsOpen=true;break;}if(state.active<state.selected.length-1)state.active++;else{state.active=0;state.reviewStage=0;go(3);return;}break;}
case 'edit-product':state.active=index;go(1);return;
case 'review-tab':state.reviewStage=index;break;
case 'next-review':if(state.reviewStage===0){const bad=state.selected.find(id=>!ready(id));if(bad){ui.error=catalog[bad].name+': '+(!state.products[bad].reviewed?'approve the design proof before continuing.':deliveryError(bad));break;}}state.reviewStage=Math.min(2,state.reviewStage+1);break;
case 'review-back':if(state.reviewStage>0)state.reviewStage--;else{state.active=state.selected.length-1;go(2);return;}break;
case 'show-promo':ui.promoOpen=true;break;
case 'apply-promo':if(ui.promoCode.trim().toUpperCase()!=='LISTING10'){ui.error='That code isn’t available. Try LISTING10.';break;}state.credits.promo=true;toast('$10.00 promo applied.');break;
case 'remove-promo':state.credits.promo=false;ui.promoCode='';break;
case 'add-card':ui.cardDraft={name:'Jordan Ellis',type:'mastercard'};openDrawer('add-card');return;
case 'save-card':state.cardAdded=true;state.cardLabel=ui.cardDraft.type==='visa'?'Visa ending in 1008':'Mastercard ending in 5556';state.payment='new';closeDrawer();toast('Example card selected for this order.');return;
case 'submit-order':{const bad=state.selected.find(id=>!ready(id));if(bad){ui.error=catalog[bad].name+' needs an approved proof and complete delivery settings.';break;}if(state.payment==='corporate'&&(!state.costCenter.trim()||!state.billingComments.trim())){ui.error='Add a cost center and billing comments for corporate billing.';break;}if(state.payment==='split'&&(Number(state.split)<0||Number(state.split)>totals().balance||!Number.isFinite(Number(state.split)))){ui.error='The first-card amount must be between $0 and the remaining balance.';break;}if(!state.ack){ui.error='Confirm that you have reviewed the proofs and order details.';break;}state.submitted=true;ui.view='';render();window.scrollTo({top:0,behavior:'instant'});return;}
case 'listing':ui.temp={event:state.event};openDrawer('listing');return;
case 'save-listing':if(state.event!==ui.temp.event){state.event=ui.temp.event;state.selected.forEach(id=>state.products[id].reviewed=false);}closeDrawer();toast('Listing event updated across all products.');return;
case 'orders':case 'account':case 'activity':case 'help':case 'confirmation-details':openDrawer(action);return;
case 'home':if(state.submitted){state=initial();go(0);return;}ui.view='';break;
case 'new-order':state=initial();ui.view='';ui.drawer='';go(0);return;
case 'close-drawer':closeDrawer();return;
default:return;
}render();}
$('#app').addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)handleAction(el.dataset.action,el);else if(e.target.matches('[data-overlay]'))closeDrawer();});
function bindValue(el){const binding=el.dataset.bind;if(!binding||binding==='readonly')return;const value=el.type==='checkbox'?el.checked:el.type==='file'?el.files[0]?.name||'':el.value;const [root,key]=binding.split('.');if(root==='product'){product()[key]=value;if(['headline','description','photo'].includes(key))product().reviewed=false;}else if(root==='credits')state.credits[key]=value;else if(root==='state')state[key]=value;else if(root==='ui'){ui[key]=value;if(key==='qrValue'){ui.qrStatus='';ui.qrOverride=false;}}else if(root==='radius'){ui.radius[key]=value;ui.radius.preview=false;}else if(root==='temp')ui.temp[key]=value;else if(root==='address')ui.sampleDraft[key]=value;else if(root==='card')ui.cardDraft[key]=value;else state[root]=value;save();}
$('#app').addEventListener('input',e=>{const el=e.target;if(['checkbox','radio','file'].includes(el.type)||el.tagName==='SELECT')return;bindValue(el);if(el.dataset.bind==='ui.listSearch'){const pos=el.selectionStart;render();const n=$('[data-bind="ui.listSearch"]');n.focus();n.setSelectionRange(pos,pos);}else if(el.dataset.bind==='ui.qrValue'){const pos=el.selectionStart;render();const n=$('[data-bind="ui.qrValue"]');n.focus();try{n.setSelectionRange(pos,pos);}catch{}}else if(el.dataset.bind==='product.headline'){const tabs=$('.product-tabs');if(tabs)tabs.outerHTML=productTabs();$('.proof-wrap').innerHTML=proof();const status=$('.support-column .status-label');if(status)status.innerHTML=icon('clock')+'Review needed';if(status)status.classList.remove('ready');const ps=$('.proof-status');if(ps){ps.classList.remove('ready');ps.innerHTML=icon('info')+'<span>Design updated. Review your proof before continuing.</span>';}}else if(el.dataset.bind==='product.qty'){const tabs=$('.product-tabs');if(tabs)tabs.outerHTML=productTabs();const col=$('.support-column');if(col)col.innerHTML=deliverySummary();const f=$('.footer-total');if(f)f.innerHTML=catalog[currentId()].name+' · '+qty(currentId())+' pieces<strong>'+money(pricing(currentId()).total)+'</strong>';}else if(el.dataset.bind==='state.split'){const col=$('.support-column');if(col)col.innerHTML=orderSummary();const amount=$('.split-allocation>strong');if(amount)amount.textContent=money(Math.max(0,totals().balance-(Number(state.split)||0)));}else if(el.dataset.bind?.startsWith('radius.')){const b=$('[data-action="confirm-radius"]');if(b){b.dataset.action='preview-radius';b.innerHTML='Preview addresses '+icon('arrow');}$('.radius-results')?.remove();$('.form-column>.success-inline')?.remove();}});
$('#app').addEventListener('change',e=>{const el=e.target;if(el.dataset.list){if(el.checked)ui.audienceDraft.push(el.dataset.list);else ui.audienceDraft=ui.audienceDraft.filter(x=>x!==el.dataset.list);render();return;}if(['checkbox','radio','file'].includes(el.type)||el.tagName==='SELECT'){bindValue(el);ui.error='';if(el.dataset.bind==='product.sample')product().optionsOpen=true;render();}});
document.addEventListener('toggle',e=>{if(e.target.matches?.('[data-options]')){product().optionsOpen=e.target.open;save();}},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.drawer){closeDrawer();return;}if(e.key==='Tab'&&ui.drawer){const focusable=[...document.querySelectorAll('.drawer button:not(:disabled),.drawer input:not(:disabled),.drawer select,.drawer textarea')].filter(x=>x.offsetParent!==null);const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
render();
